<script lang="ts">
  import { onMount } from "svelte";
  import { api } from "../api";
  export let onClose: () => void;
  let dashboard: any = null, users: any[] = [], detail: any = null, expandedId = "", query = "", page = 1, total = 0, loading = true, error = "";
  const fmt = (n: number) => new Intl.NumberFormat().format(n || 0);
  const date = (v: string) => v ? new Date(v).toLocaleString() : "Never";
  const value = (v: string | null | undefined) => v || "Not provided";
  async function loadUsers() { const data = await api.getAdminUsers(query, page); users = data.items; total = data.total; expandedId = ""; detail = null; }
  async function load() { loading = true; error = ""; try { dashboard = await api.getAdminDashboard(); await loadUsers(); } catch (e) { error = e instanceof Error ? e.message : "Unable to load admin data"; } finally { loading = false; } }
  async function toggleUser(id: string) { if (expandedId === id) { expandedId = ""; detail = null; return; } try { error = ""; detail = await api.getAdminUser(id); expandedId = id; } catch (e) { error = e instanceof Error ? e.message : "Unable to load user"; } }
  async function toggleProjectUnlock(user: any, event?: MouseEvent) {
    event?.stopPropagation();
    try {
      error = "";
      const unlocked = !Boolean(user.project_limit_unlocked);
      await api.setAdminProjectLimit(user.id, unlocked);
      user.project_limit_unlocked = unlocked;
      if (detail?.user?.id === user.id) detail.user.project_limit_unlocked = unlocked;
    } catch (e) { error = e instanceof Error ? e.message : "Unable to update project access"; }
  }
  async function search() { page = 1; await loadUsers(); }
  onMount(load);
</script>

<div class="admin-shell">
  <header><div><strong>Hardcore AI Admin</strong><span>Usage and account reporting</span></div><button onclick={onClose}>Back to IDE</button></header>
  {#if loading}<p class="state">Loading administrator data?</p>
  {:else if error}<div class="state error">{error}<button onclick={load}>Retry</button></div>
  {:else}
    <section><div class="cards"><article><b>{fmt(dashboard.users)}</b><span>Users</span></article><article><b>{fmt(dashboard.projects)}</b><span>Projects</span></article><article><b>{fmt(dashboard.requests)}</b><span>AI Requests</span></article><article><b>{fmt(dashboard.input_tokens)}</b><span>Input Tokens</span></article><article><b>{fmt(dashboard.output_tokens)}</b><span>Output Tokens</span></article><article><b>{fmt(dashboard.total_tokens)}</b><span>Total Tokens</span></article></div>
    <h3>Usage (last 30 days)</h3><div class="usage">{#if dashboard.usage_over_time.length}{#each dashboard.usage_over_time as d}<div title={`${d.date}: ${fmt(d.total_tokens)} tokens`} style={`height:${Math.max(5, Math.min(100, (d.total_tokens / Math.max(...dashboard.usage_over_time.map((x:any)=>x.total_tokens || 1))) * 100))}%`}></div>{/each}{:else}<p class="empty">No AI usage recorded in this period.</p>{/if}</div>
    <div class="users-head"><h3>Users</h3><input placeholder="Search name or email" bind:value={query} onkeydown={(e) => e.key === "Enter" && search()} /><button onclick={search}>Search</button></div>
    {#if users.length}<table><thead><tr><th>Profile</th><th>Name</th><th>Email</th><th>Phone</th><th>Company</th><th>Projects</th><th>Paid interest</th><th>Project Access</th><th></th></tr></thead><tbody>{#each users as u}<tr class="click" class:expanded={expandedId === u.id} onclick={() => toggleUser(u.id)}><td>{#if u.avatar_url}<img src={u.avatar_url} alt="" />{:else}?{/if}</td><td>{u.name}</td><td><a href={`mailto:${u.email}`} onclick={(event) => event.stopPropagation()}>{u.email}</a></td><td>{value(u.phone_number)}</td><td>{value(u.company_name)}</td><td>{u.projects}</td><td>{u.willing_to_pay === true ? "Yes" : u.willing_to_pay === false ? "No" : "No response"}</td><td><button class="access-toggle" class:unlocked={u.project_limit_unlocked} onclick={(event) => toggleProjectUnlock(u, event)}>{u.project_limit_unlocked ? "Unlocked" : "2-project limit"}</button></td><td class="chevron" aria-label={expandedId === u.id ? "Collapse user details" : "Expand user details"}>{expandedId === u.id ? "?" : "?"}</td></tr>
      {#if expandedId === u.id && detail}<tr class="details"><td colspan="9"><div class="details-grid"><div><h4>User Details</h4><dl><dt>Name</dt><dd>{detail.user.name}</dd><dt>Email</dt><dd><a href={`mailto:${detail.user.email}`}>{detail.user.email}</a></dd><dt>Phone</dt><dd>{value(detail.user.phone_number)}</dd><dt>Company / Organization</dt><dd>{value(detail.user.company_name)}</dd><dt>Role</dt><dd>{value(detail.user.role)}</dd><dt>What they do</dt><dd>{value(detail.user.about)}</dd><dt>Primary use case</dt><dd>{value(detail.user.primary_use_case)}</dd><dt>Company size</dt><dd>{value(detail.user.company_size)}</dd><dt>How they heard about us</dt><dd>{value(detail.user.referral_source)}</dd><dt>Willing to pay</dt><dd>{detail.user.willing_to_pay === true ? "Yes" : detail.user.willing_to_pay === false ? "No" : "No response"}</dd><dt>Feedback</dt><dd>{value(detail.user.project_limit_feedback)}</dd><dt>Project access</dt><dd><button class="access-toggle" class:unlocked={detail.user.project_limit_unlocked} onclick={(event) => toggleProjectUnlock(detail.user, event)}>{detail.user.project_limit_unlocked ? "Unlocked — unlimited projects" : "Limited to 2 projects"}</button></dd><dt>Joined</dt><dd>{date(detail.user.created_at)}</dd></dl></div><div class="activity"><h4>Activity</h4><p><b>{fmt(detail.usage.ai_requests)}</b> AI requests ? <b>{fmt(detail.projects.length)}</b> projects</p>{#if detail.projects.length}<ul>{#each detail.projects.slice(0, 5) as p}<li>{p.name} <span>{date(p.updated_at)}</span></li>{/each}</ul>{:else}<p class="empty">No projects yet.</p>{/if}</div></div></td></tr>{/if}{/each}</tbody></table>{:else}<p class="empty">No users match this search.</p>{/if}
    <div class="pager"><button disabled={page === 1} onclick={async()=>{page--; await loadUsers()}}>Previous</button><span>Page {page} ? {total} users</span><button disabled={page * 25 >= total} onclick={async()=>{page++; await loadUsers()}}>Next</button></div></section>
  {/if}
</div>

<style>
.admin-shell{box-sizing:border-box;height:100vh;overflow-y:auto;overscroll-behavior:contain;padding:22px 32px 40px;background:var(--bg-primary,#09090f);color:var(--text-bright,#f4f4f5);font:14px var(--font-sans,system-ui)}header{display:flex;justify-content:space-between;align-items:center;max-width:1400px;margin:0 auto 22px}header strong{display:block;font-size:20px}header span,.empty,.state{color:var(--text-muted,#a1a1aa)}section{max-width:1400px;margin:auto}.cards{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.cards article{padding:15px 17px;background:var(--bg-secondary,#11111a);border:1px solid var(--border-color,#292938);border-radius:8px}.cards b,.cards span{display:block}.cards b{font-size:22px}.cards span{margin-top:5px;color:var(--text-muted,#a1a1aa);font-size:12px}h3{margin:22px 0 10px}.usage{height:96px;padding:12px;display:flex;align-items:end;gap:5px;background:var(--bg-secondary,#11111a);border:1px solid var(--border-color,#292938);border-radius:8px}.usage div{flex:1;min-width:4px;background:var(--accent-violet,#7c3aed);border-radius:3px 3px 0 0}.usage .empty{margin:auto}.users-head{display:flex;align-items:center;gap:8px}.users-head h3{margin-right:auto}input,button{background:var(--bg-tertiary,#191923);border:1px solid var(--border-color,#292938);color:inherit;border-radius:6px;padding:8px 10px}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}table{width:100%;border-collapse:collapse;background:var(--bg-secondary,#11111a);border:1px solid var(--border-color,#292938);border-radius:8px;overflow:hidden}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--border-color,#292938);vertical-align:top}th{font-size:11px;text-transform:uppercase;color:var(--text-muted,#a1a1aa)}tr.click{cursor:pointer}tr.click:hover,tr.expanded{background:var(--bg-tertiary,#191923)}td img{width:28px;height:28px;border-radius:50%;object-fit:cover}a{color:inherit}.chevron{font-size:18px;text-align:center}.details td{padding:0}.details-grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(220px,.6fr);gap:24px;padding:20px;background:#0d0d15}.details h4{margin:0 0 12px;font-size:14px}.details h4{margin:0 0 12px;font-size:14px}.details dl{display:grid;grid-template-columns:150px 1fr;gap:8px 14px;margin:0}.details dt{color:var(--text-muted,#a1a1aa)}.details dd{margin:0;white-space:pre-wrap}.activity{border-left:1px solid var(--border-color,#292938);padding-left:24px}.activity b{display:inline;font-size:inherit}.activity ul{padding-left:18px}.activity li{margin:8px 0}.activity li span{display:block;font-size:11px;color:var(--text-muted,#a1a1aa)}.pager{margin:14px 0;display:flex;justify-content:flex-end;gap:12px;align-items:center}.error{color:#fca5a5}.access-toggle{padding:5px 8px;font-size:11px;border-color:rgba(239,68,68,.35);color:#fca5a5}.access-toggle.unlocked{border-color:rgba(16,185,129,.4);color:#6ee7b7;background:rgba(16,185,129,.08)}@media(max-width:1000px){.cards{grid-template-columns:repeat(3,1fr)}table{display:block;overflow:auto}.details-grid{grid-template-columns:1fr}.activity{border-left:0;border-top:1px solid var(--border-color,#292938);padding:16px 0 0}.details dl{grid-template-columns:130px 1fr}}@media(max-width:650px){.cards{grid-template-columns:repeat(2,1fr)}.admin-shell{padding:16px}.users-head{align-items:stretch;flex-wrap:wrap}.users-head h3{width:100%;margin-bottom:0}}
</style>
